    Turno = apps.get_model("tallermami", "Turno")
    Vehiculo = apps.get_model("tallermami", "Vehiculo")
    User = apps.get_model(*settings.AUTH_USER_MODEL.split("."))
    db_alias = schema_editor.connection.alias

    users = User.objects.using(db_alias).exclude(email="").order_by("pk")
    for user in users:
        email = user.email.strip()
        if not email or User.objects.using(db_alias).filter(
            email__iexact=email
        ).count() != 1:
            continue

        cliente = Cliente.objects.using(db_alias).filter(
            email__iexact=email
        ).first()
        if cliente is None:
            cliente = Cliente.objects.using(db_alias).create(
                nombre=user.first_name or user.username,
                apellido=user.last_name or "",
                email=email,
                telefono="",
            )

        if cliente.usuario_id in (None, user.pk):
            cliente.usuario_id = user.pk
            cliente.save(using=db_alias, update_fields=["usuario"])

    for turno in Turno.objects.using(db_alias).all().iterator():
        cliente = None
        if turno.usuario_id:
            usuario = User.objects.using(db_alias).filter(
                pk=turno.usuario_id
            ).first()
            if usuario and usuario.email:
                clientes = Cliente.objects.using(db_alias).filter(
                    email__iexact=usuario.email.strip()
                )
                if clientes.count() == 1:
                    cliente = clientes.first()

        vehiculo = Vehiculo.objects.using(db_alias).filter(
            cliente_id=cliente.pk if cliente else None,
            patente__iexact=turno.patente,
        ).first()
        if vehiculo is None:
            vehiculo = Vehiculo.objects.using(db_alias).create(
                cliente_id=cliente.pk if cliente else None,
                marca=turno.marca,
                modelo=turno.modelo or turno.vehiculo,
                anio=turno.anio,
                patente=turno.patente,
            )
        else:
            if not vehiculo.marca:
                vehiculo.marca = turno.marca
            if not vehiculo.modelo:
                vehiculo.modelo = turno.modelo or turno.vehiculo
            if vehiculo.anio is None:
                vehiculo.anio = turno.anio
            vehiculo.save(
                using=db_alias,
                update_fields=["marca", "modelo", "anio"],
            )

        fecha_turno_local = django.utils.timezone.localtime(
            turno.fecha_turno
        )
        disponibilidad = Disponibilidad.objects.using(db_alias).create(
            fecha=fecha_turno_local.date(),
            hora=fecha_turno_local.time(),
            estado=turno.estado == "cancelado",
        )
        turno.cliente_id = cliente.pk if cliente else None
        turno.vehiculo_registrado_id = vehiculo.pk
        turno.disponibilidad_id = disponibilidad.pk
        turno.save(
            using=db_alias,
            update_fields=[
                "cliente",
                "vehiculo_registrado",
                "disponibilidad",
            ],
        )


